import{_ as c,r as o,o as d,c as l,e as s,a as n,s as r}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"子主题 - October CMS - 3.x","titleTemplate":false,"description":"通过创建子版本来覆盖主题。","frontmatter":{"subtitle":"通过创建子版本来覆盖主题。"},"headers":[{"level":2,"title":"主题锁定文件","slug":"主题锁定文件","link":"#主题锁定文件","children":[]},{"level":2,"title":"创建新的子主题","slug":"创建新的子主题","link":"#创建新的子主题","children":[]}],"relativePath":"3.x/zh-cn/cms/themes/child-themes.md","filePath":"3.x/zh-cn/cms/themes/child-themes.md"}'),p={name:"3.x/zh-cn/cms/themes/child-themes.md"};function h(i,e,m,_,g,u){const a=o("pre-heading"),t=o("post-heading");return d(),l("div",null,[s(a),e[0]||(e[0]=n("h1",null,"子主题",-1)),s(t),e[1]||(e[1]=r(`<p>子主题提供了主题继承的可能性。一个很好的用途是当您有一个第三方主题或处于只读模式的主题时。子主题将引用一个父主题，并将其用作备用来源。</p><p>如果一个名为 <code>home.htm</code> 的页面存在于父主题中但不存在于子主题中，系统会将其视为存在一样处理；URL 是活动的，您可以像正常一样打开该页面。在后端区域保存页面时，会在子主题中创建一个新文件来覆盖内容。</p><p>要为主题启用此功能，请导航到<strong>设置 → 前端主题</strong>，选择<strong>编辑属性</strong>，然后从<strong>父主题</strong>下拉列表中选择一个父主题。</p><h2 id="主题锁定文件"><a href="#主题锁定文件" class="header-anchor">#</a> 主题锁定文件</h2><p>使用 Composer 从第三方安装主题时，需要注意的是，当主题更新时，所有文件都可能被覆盖。这可能导致对主题所做的任何自定义更改丢失。作为安全机制，包含了一个名为 <code>.themelock</code> 的文件来保护主题免受系统更新期间可能丢失的任何更改。</p><p>当主题目录中存在 <code>.themelock</code> 文件时：</p><ul><li>该主题只能被选择为父主题</li><li>该主题不会出现在后端 UI 中</li><li>该主题无法被选择为活动主题</li></ul><h2 id="创建新的子主题"><a href="#创建新的子主题" class="header-anchor">#</a> 创建新的子主题</h2><p><code>theme:copy</code> 命令可用于创建新主题，包括子主题。以下命令通过复制目录及其内容，从源主题 <code>demo</code> 创建一个名为 <code>demo-copy</code> 的新主题。在此过程中将删除 <code>.themelock</code> 文件。</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan theme:copy demo demo-copy
</code></pre></div><p>要创建继承父主题的子主题，请指定 <code>--child</code> 选项。</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan theme:copy demo demo-child <span class="token parameter variable">--child</span>
</code></pre></div>`,12))])}const x=c(p,[["render",h]]);export{v as __pageData,x as default};
